    /** What a bulk open did: how many it opened and refused, and the claims it opened. */
    public record BulkOpened(int opened, int refused, List<Claim> claims) {
    }

    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
     *  refused, as is one not on the sheet. */
    @Transactional
    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
        Set<Long> chosen = new HashSet<>(claimIds);
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            return new BulkOpened(0, chosen.size(), List.of());
        }
        List<Claim> opened = new ArrayList<>();
        for (Claim claim : inListOrder(sheetId, chosen)) {
            try {
                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException
                    | ActionNotAllowedException | ClaimNoteException | ClaimCapException e) {
                // refused: left as it is
            }
        }
        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
    }

    /** What a bulk settle did: how many it settled (PENDING included) and refused, the claims it changed, and

    /** How many a bulk re-date re-dated and refused, and the claims it re-dated. */
    public record BulkRedateView(int redated, int refused, List<ClaimView> claims) {
    }

    /** Re-date the chosen claims together, in list order; each that cannot be re-dated is left as it is. */
    @PostMapping("/claims/bulk-redate")
    public BulkRedateView bulkRedate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid BulkRedateRequest request) {
        ClaimService.BulkRedated done = service.bulkRedate(sheetId.trim(), user.trim(), request.claimIds(),
                request.date());
        return new BulkRedateView(done.redated(), done.refused(),
                done.claims().stream().map(ClaimView::of).toList());
    }

    /** Settle an OPEN claim; a clerk settling a due above the clerk limit puts it PENDING instead. */
    @PostMapping("/claims/{claimId}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.SETTLED));
    }

    /** Approve a PENDING claim: a steward other than its opener settles it. */
    @PostMapping("/claims/{claimId}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.approve(sheetId.trim(), user.trim(), claimId));
    }

